CREATE OR REPLACE FUNCTION public.persist_import_drafts(_workspace uuid,_key text,_kind text,_source text,_rows jsonb,_problems jsonb,_upload uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE job uuid;r jsonb;ids uuid[]:='{}';d uuid;BEGIN
IF _kind NOT IN ('passenger','delivery') OR _source NOT IN ('csv','xlsx','pdf') OR _key!~'^[a-f0-9]{64}$' OR jsonb_typeof(_rows)<>'array' OR jsonb_array_length(_rows) NOT BETWEEN 1 AND 250 THEN RAISE EXCEPTION 'Invalid import';END IF;
IF NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_workspace AND m.user_id=auth.uid() AND m.removed_at IS NULL AND NOT m.is_contractor AND (m.role IN ('owner','admin') OR m.can_create_requests) AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Import account unavailable';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||_key,0));
IF EXISTS(SELECT 1 FROM public.csv_import_jobs WHERE user_id=auth.uid() AND idempotency_key=_key) THEN RETURN jsonb_build_object('duplicateFile',true,'created',0,'failed',0,'total',jsonb_array_length(_rows));END IF;
IF _upload IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.upload_originals WHERE id=_upload AND user_id=auth.uid() AND workspace_id=_workspace AND deleted_at IS NULL AND expires_at>now()) THEN RAISE EXCEPTION 'Original unavailable';END IF;
INSERT INTO public.csv_import_jobs(user_id,workspace_id,kind,idempotency_key,total_rows,source_type,status,error_summary,actor_mfn_id,workspace_mfn_id) VALUES(auth.uid(),_workspace,_kind,_key,jsonb_array_length(_rows),_source,'processing',_problems,(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),(SELECT mfn_id FROM public.workspaces WHERE id=_workspace)) RETURNING id INTO job;
FOR r IN SELECT * FROM jsonb_array_elements(_rows) LOOP
IF jsonb_typeof(r->'data')<>'object' OR (r->>'row')::int<1 THEN RAISE EXCEPTION 'Invalid draft row';END IF;
INSERT INTO public.trip_drafts(user_id,workspace_id,payload,summary,autosaved,import_job_id,import_row,source) VALUES(auth.uid(),_workspace,r->'data',left(coalesce(r->>'summary','Imported trip draft'),240),false,job,(r->>'row')::int,_source) RETURNING id INTO d;ids:=array_append(ids,d);
END LOOP;
UPDATE public.csv_import_jobs SET status='completed',submitted_rows=cardinality(ids),failed_rows=0,draft_ids=ids WHERE id=job;
IF _upload IS NOT NULL THEN UPDATE public.upload_originals SET import_job_id=job WHERE id=_upload;END IF;
RETURN jsonb_build_object('duplicateFile',false,'created',cardinality(ids),'failed',0,'total',jsonb_array_length(_rows));END $$;
REVOKE ALL ON FUNCTION public.persist_import_drafts(uuid,text,text,text,jsonb,jsonb,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.persist_import_drafts(uuid,text,text,text,jsonb,jsonb,uuid) TO authenticated;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='persist_provider_draft_quote';d:=replace(d,'v.effective_at<=now()', '(v.effective_at AT TIME ZONE ''America/New_York'')::date<=(_snapshot->''trip''->>''pickupDate'')::date AND (v.effective_end IS NULL OR v.effective_end>=(_snapshot->''trip''->>''pickupDate'')::date) AND v.agreement_active AND (v.payer_id IS NULL OR v.payer_id::text=d.payload->>''payerId'')');EXECUTE d;END $$;